1068: # The console output of a member (its stdout, then its stderr file; UTF-8) as lines.
1069: function Read-PanelMemberOutput {
1070:     param($Slot)
1071:     $lines = New-Object System.Collections.Generic.List[string]
1072:     foreach ($f in @($Slot.OutPath, $Slot.ErrPath)) {
1073:         if (-not $f) { continue }
1074:         $t = Read-SharedText -Path $f
1075:         if (-not $t -or -not $t.Trim()) { continue }
1076:         foreach ($l in ($t.TrimEnd() -split "`r?`n")) { $lines.Add($l) }
1077:     }
1078:     return , ([string[]]$lines.ToArray())
1079: }
