1081: # Starts one member: its spec (base64 of UTF-8 JSON on the command line, as before), its console
1082: # output to <temp>/codex-consult-panel-<id>/<NN>.out|.err, stdin from an empty file. Reads the
1083: # panel run's variables; sets the slot's Proc / Watch / State ('running' | 'failed-start').
1084: function Start-PanelMember {
1085:     param($Slot)
1086:     $pm = $Slot.Pm
1087:     # The members whose files this member's agy tree check leaves out (D7): deliberately the
1088:     # UNION of all other slots whenever the plan lets any two members run at once - not only
1089:     # those the scheduler can actually run beside this one (F11-5). That costs no evidence: an
1090:     # ignored path that did not change hides nothing, and one that changed was written by a
1091:     # member running meanwhile (or by this member's own reviewer - the D7 residual the README
1092:     # names: the ignored paths are the task's stores and the other members' handoff names).
1093:     $siblings = @()
1094:     if ($panelPlan.Effective -gt 1) { $siblings = @($panelSlots | Where-Object { $_.K -ne $Slot.K } | ForEach-Object { [string]$_.Nn }) }
1095:     $spec = [pscustomobject]@{
1096:         id                = $panelId
1097:         position          = $Slot.K
1098:         of                = $panelRunners.Count
1099:         members           = $panelMembersRecord
1100:         roster_position   = $pm.Entry.Position
1101:         provider          = $pm.Entry.Provider
1102:         model             = $pm.Entry.Model
1103:         engine            = [string]$pm.Entry.Engine
1104:         skipped           = $panelSkippedRecord
1105:         listed_ids        = [object[]]$panelListed
1106:         n                 = $Slot.N
1107:         nn                = $Slot.Nn
1108:         consult_id        = $Slot.ConsultId
1109:         parent_pid        = $PID
1110:         parent_start_time = $panelParentStart
1111:         sibling_nns       = [object[]]$siblings
1112:         concurrency       = $panelPlan.Effective
1113:         limits            = $panelLimits
1114:         args              = [pscustomobject]@{
1115:             collab_dir       = $CollabDir
1116:             mode             = $Mode
1117:             brief            = $Brief
1118:             prompt           = $Prompt
1119:             purpose          = $Purpose
1120:             effort           = $Effort
1121:             sandbox          = $Sandbox
1122:             max_words        = $MaxWords
1123:             timeout_sec      = $TimeoutSec
1124:             reply_name       = $Slot.ReplyName
1125:             artifact         = [object[]]@($Artifact)
1126:             raw              = [bool]$Raw
1127:             codex_exe        = $CodexExe
1128:             native_effort    = $NativeEffort
1129:             off_peak_only    = [bool]$OffPeakOnly
1130:             skip_preflight   = [bool]$SkipPreflight
1131:             codex_config     = [object[]]@($CodexConfig)
1132:             schema_transport = $transportOverride
1133:             format_retry     = $FormatRetry
1134:             engine           = $Engine
1135:             engine_exe       = $EngineExe
1136:             denial_retry     = $DenialRetry
1137:             max_model_steps  = $MaxModelSteps
1138:             dry_run          = [bool]$DryRun
1139:         }
1140:     }
1141:     $specB64 = [Convert]::ToBase64String($script:Utf8NoBom.GetBytes((ConvertTo-Json -InputObject $spec -Depth 8 -Compress)))
1142:     $Slot.OutPath = Join-Path $panelTmp "$($Slot.Nn).out"
1143:     $Slot.ErrPath = Join-Path $panelTmp "$($Slot.Nn).err"
1144:     $argLine = (@('-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', $panelSelf, '-Task', $Task, '-PanelSpec', $specB64) | ForEach-Object { ConvertTo-ProcArg $_ }) -join ' '
1145:     try {
1146:         $Slot.Proc = Start-Process -FilePath $panelHost -ArgumentList $argLine -WorkingDirectory $callerCwd -NoNewWindow -PassThru `
1147:             -RedirectStandardOutput $Slot.OutPath -RedirectStandardError $Slot.ErrPath -RedirectStandardInput $panelEmptyIn
1148:         # PS 5.1: touch .Handle right away, or .ExitCode comes back empty (see the run below)
1149:         if ($script:LegacyPS) { try { $null = $Slot.Proc.Handle } catch { } }
1150:         $Slot.Watch = [System.Diagnostics.Stopwatch]::StartNew()
1151:         $Slot.State = 'running'
1152:     } catch {
1153:         $Slot.State = 'failed-start'
1154:         $Slot.StartError = ConvertTo-OneLine $_.Exception.Message
1155:     }
1156: }
