1158: # A finished (or stopped) member: its console output, its refusal line, its ledger entry and
1159: # what became of its recovery record.
1160: function Complete-PanelMember {
1161:     param($Slot)
1162:     $Slot.Lines = Read-PanelMemberOutput $Slot
1163:     $last = @($Slot.Lines | Where-Object { $_ -match '^codex-consult: ' }) | Select-Object -Last 1
1164:     $Slot.Refusal = $(if ($last) { $last -replace '^codex-consult: ', '' } else { "exit $($Slot.Exit)" })
1165:     if (-not $DryRun) {
1166:         $Slot.Entry = Find-PanelEntry -Path $sessionsPath -PanelId $panelId -Position $Slot.K
1167:         $rd = Read-PendingFile -Path $Slot.RecordPath
1168:         $Slot.RecordState = $(if ($rd.Exists -and $rd.Record) { [string](Get-PropertyValue $rd.Record 'state' '') } else { '' })
1169:     }
1170: }
1171: 
1172: # One phrase for a member that ran (the progress line; the summary builds on it).
1173: function Get-PanelMemberStatus {
1174:     param($Slot)
1175:     if ($Slot.State -eq 'killed') { return "killed by the panel after $($Slot.Wall) s (its guard: $($Slot.Guard) s)" }
1176:     if ($Slot.State -eq 'failed-start') { return "failed: could not start the member process - $($Slot.StartError)" }
1177:     if ($DryRun) { if ($Slot.Exit -eq 0) { return 'planned' } else { return "refused: $(ConvertTo-OneLine $Slot.Refusal)" } }
1178:     if ($null -ne $Slot.Entry) { return [string](Get-PropertyValue $Slot.Entry 'bridge_outcome' '') }
1179:     if ($Slot.RecordState -eq 'committing') {
1180:         # D3: the write lock never acquired (the member says so) - or stopped INSIDE its commit
1181:         # (a kill, a crash: its findings may be ORPHAN; the record names the kept reply)
1182:         if ($Slot.Refusal -match '^commit blocked:') { return "commit blocked: $(ConvertTo-OneLine ($Slot.Refusal -replace '^commit blocked:\s*', ''))" }
1183:         return "failed: stopped inside its commit (exit $($Slot.Exit)); findings it wrote have no ledger entry (ORPHAN)"
1184:     }
1185:     return "failed: $(ConvertTo-OneLine $Slot.Refusal)"
1186: }
1187: 
1188: if ($panelRun) {
1189:     # What would make every member fail the same way is refused once, up front.
1190:     if ($Brief) {
1191:         $briefProbe = $Brief
1192:         if (-not [IO.Path]::IsPathRooted($briefProbe)) {
1193:             foreach ($base in @($callerCwd, $repoRoot)) {
1194:                 if (Test-Path -LiteralPath (Join-Path $base $briefProbe) -PathType Leaf) { $briefProbe = Join-Path $base $briefProbe; break }
1195:             }
1196:         }
1197:         if (-not (Test-Path -LiteralPath $briefProbe -PathType Leaf)) {
1198:             Stop-WithError "brief '$Brief' not found (this script never writes briefs; write it first)."
1199:         }
1200:     }
1201:     if (-not $DryRun -and -not $codexExePath -and @($roster.Entries | Where-Object { $_.Engine -eq 'codex' -and (-not $Engine -or $Engine -eq 'codex') }).Count -gt 0) {
1202:         Stop-WithError "codex CLI not found on PATH (set -CodexExe <path> or the CODEX_CONSULT_EXE environment variable)."
1203:     }
1204:     $panelConfig = Read-CodexConfigSubset -Path (Get-CodexConfigPath)
1205:     $panelClock = Get-ConsultClock -Peek
1206:     if ($panelClock.Error) { Stop-WithError $panelClock.Error }
1207:     $panelSelection = Select-PanelMembers -Roster $roster -Config $panelConfig -Consults (Read-AllTaskConsults -CollabRoot $collabRoot) -Launcher ([string]$codexExePath) -LoginCache @{} -UtcNow $panelClock.Now.UtcDateTime -OpenAiBaseUrl ([string]$env:OPENAI_BASE_URL) -Model $Model -Purpose $Purpose -All:$PanelAll -SkipPreflight:$SkipPreflight -Engine $Engine -EngineLaunchers $engineLaunchers
1208:     if ($panelSelection.Error) { Stop-WithError $panelSelection.Error }
1209:     $panelEntries = @($panelSelection.Members)
1210:     $panelRunners = @($panelEntries | Where-Object { $_.State -eq 'run' })
1211:     # -MaxModelSteps goes to the members whose engine has a step cap (muse); none -> refused.
1212:     if ($MaxModelSteps -gt 0 -and @($panelRunners | Where-Object { (Get-EngineSpec ([string]$_.Entry.Engine)).StepsFlag }).Count -eq 0) {
1213:         Stop-WithError "-MaxModelSteps applies to the muse members of a panel (--max-model-steps); no member of this panel runs the muse engine."
1214:     }
1215:     # A launcher every member of an engine would miss is refused once, up front.
1216:     if (-not $DryRun) {
1217:         foreach ($panelEngine in @($panelRunners | ForEach-Object { [string]$_.Identity.Engine } | Select-Object -Unique)) {
1218:             if ($panelEngine -ne 'codex' -and -not (Get-EngineLauncher -Engine $panelEngine -Launchers $engineLaunchers)) {
1219:                 Stop-WithError "$panelEngine CLI not found on PATH (set -EngineExe <path> or the $((Get-EngineSpec $panelEngine).ExeEnv) environment variable)."
1220:             }
1221:         }
1222:     }
1223:     $panelId = [guid]::NewGuid().ToString()
1224:     $panelShort = $panelId.Substring(0, 8)
1225:     $panelMembersRecord = [object[]]@($panelEntries | ForEach-Object { [pscustomobject]@{ provider = $_.Entry.Provider; model = $_.Identity.Model; state = $_.State; reason = $_.Reason } })
1226:     $panelSkippedRecord = [object[]]@($panelEntries | Where-Object { $_.State -ne 'run' } | ForEach-Object { [pscustomobject]@{ provider = $_.Entry.Provider; model = $_.Identity.Model; engine = [string]$_.Entry.Engine; reason = $_.Reason } })
1227:     # The plan (D8): endpoint groups, the roster's "parallel", -PanelConcurrency.
1228:     $panelPlan = Get-PanelPlan -Runners $panelRunners -Parallel $roster.Parallel -Cap $PanelConcurrency
1229:     $panelLimits = [pscustomobject]$panelPlan.Limits
1230:     $panelParentStart = [string](Get-ProcessStartIso -ProcessId $PID)
1231:     $panelSelf = $PSCommandPath
1232:     $panelHost = (Get-Process -Id $PID).Path
1233:     $panelTmp = Join-Path ([IO.Path]::GetTempPath()) "codex-consult-panel-$panelId"
1234:     $panelEmptyIn = Join-Path $panelTmp 'stdin.empty'
1235:     $panelLock = $null
1236:     $panelSlots = New-Object System.Collections.Generic.List[object]
1237:     $panelWatch = [System.Diagnostics.Stopwatch]::StartNew()
1238:     try {
1239:         if (-not $DryRun) {
1240:             [void][IO.Directory]::CreateDirectory($handoffsDir)
1241:             $panelLock = Enter-TaskLock -TaskDir $taskDir -Task $Task -Panel $panelId
1242:             if (-not $panelLock.Acquired) { Stop-WithError $panelLock.Message }
1243:         }
1244:         # Every recovery record of the task, judged before anything is written: an active one
1245:         # refuses the panel (a dry run reports it); the others are consumed below.
1246:         $panelPending = Read-TaskPendingRecords -TaskDir $taskDir
1247:         if ($panelPending.Error) { Stop-WithError $panelPending.Error }
1248:         $panelPendingRefusal = ''
1249:         if ($panelPending.Active) {
1250:             if ($DryRun) { $panelPendingRefusal = [string]$panelPending.Active.Check.Message } else { Stop-WithError $panelPending.Active.Check.Message }
1251:         }
1252:         # The numbers of every member, past everything on disk (a store that does not parse
1253:         # refuses here, before any member starts).
1254:         $panelSessions = Read-JsonStore -Path $sessionsPath
1255:         $panelConsults = @()
1256:         if ($null -ne $panelSessions) { $panelConsults = @(Get-PropertyValue (Get-PropertyValue $panelSessions 'codex' $null) 'consults' @() | Where-Object { $_ }) }
1257:         $panelStore = Read-FindingsFile -Path $findingsPath -Task $Task
1258:         $panelNumbers = Get-NextNumbers -Consults $panelConsults -Store $panelStore -HandoffsDir $handoffsDir -Leftovers @($panelPending.Items | ForEach-Object { $_.Record })
1259:         # The findings every member is shown: those open when the panel starts.
1260:         $panelListed = @()
1261:         if (-not $Raw) {
1262:             $panelListed = @(@($panelStore.findings) | Where-Object { $_ -and $script:OpenStatuses -contains [string](Get-PropertyValue $_ 'status' '') } | ForEach-Object { [string]$_.id })
1263:         }
1264:         $guardHook = 0
1265:         [void][int]::TryParse([string]$env:CODEX_CONSULT_TEST_PANEL_GUARD_SEC, [ref]$guardHook)
1266:         $slotOf = @{}
1267:         $k = 0
1268:         foreach ($pm in $panelRunners) {
1269:             $k++
1270:             $slug = ($pm.Entry.Provider.ToLowerInvariant() -replace '[^a-z0-9._-]', '-').Trim('-')
1271:             if (-not $slug) { $slug = 'reviewer' }
1272:             $engineK = [string]$pm.Entry.Engine
1273:             if (-not $engineK) { $engineK = 'codex' }
1274:             $nnK = '{0:D2}' -f ([int]$panelNumbers.Nn + $k - 1)
1275:             # The kill guard from the member's own budgets (D11): its timeout, one format-repair
1276:             # turn and (an engine with a denial retry: agy) one denial-retry turn of
1277:             # min(timeout, 300) s when enabled, the 60 s write-lock wait, 120 s slack. TEST HOOK:
1278:             # CODEX_CONSULT_TEST_PANEL_GUARD_SEC.
1279:             $guard = $TimeoutSec + 60 + 120
1280:             if ($repairEnabled) { $guard += [Math]::Min($TimeoutSec, 300) }
1281:             if ((Get-EngineSpec $engineK).DenialRetry -and $DenialRetry -eq 1) { $guard += [Math]::Min($TimeoutSec, 300) }
1282:             if ($guardHook -gt 0) { $guard = $guardHook }
1283:             $slot = [pscustomobject]@{
1284:                 Pm = $pm; K = $k; N = ($panelNumbers.N + $k - 1); Nn = $nnK; Engine = $engineK
1285:                 ReplyName = "$ReplyName-$slug"; Reply = "handoffs/$nnK-$((Get-EngineSpec $engineK).Prefix)-$ReplyName-$slug.md"
1286:                 RecordPath = (Get-MemberPendingPath -TaskDir $taskDir -Nn $nnK); ConsultId = [guid]::NewGuid().ToString()
1287:                 Group = [int]$panelPlan.GroupOf[[int]$pm.Entry.Position]; Guard = $guard
1288:                 State = 'waiting'; Proc = $null; Watch = $null; Exit = $null; Wall = 0; OutPath = ''; ErrPath = ''
1289:                 Entry = $null; Refusal = ''; RecordState = ''; RecordKept = $false; NotStarted = ''; StartError = ''; Lines = [string[]]@()
1290:             }
1291:             $panelSlots.Add($slot)
1292:             $slotOf[[int]$pm.Entry.Position] = $slot
1293:         }
1294: 
1295:         $panelVerb = if ($DryRun) { 'would run' } else { 'run' }
1296:         Write-Host "Panel $panelShort$(if ($DryRun) { ' (dry run - nothing is executed or written)' }): $($panelRunners.Count) of $($panelEntries.Count) roster entries $panelVerb, $($panelPlan.Text) (roster $($roster.Path); panel id $panelId)"
1297:         # The lineage as shown: ' [agy]' for a member of another engine than codex.
1298:         foreach ($pm in $panelEntries) { $pm | Add-Member -NotePropertyName 'Shown' -NotePropertyValue (Format-ReviewerLineage -Provider $pm.Identity.Provider -Model $pm.Identity.Model -Engine ([string]$pm.Identity.Engine)) -Force }
1299:         foreach ($pm in $panelEntries) {
1300:             $slot = $slotOf[[int]$pm.Entry.Position]
1301:             Write-Host ("  #{0} {1} - {2}" -f $pm.Entry.Position, $pm.Shown, $(if ($pm.State -eq 'run') { "member, n=$($slot.N), handoff $($slot.Nn)" } else { "skipped: $($pm.Reason)" }))
1302:         }
1303:         $groupTexts = @(foreach ($g in $panelPlan.Groups) {
1304:                 $cnt = @($g.Positions).Count
1305:                 $t = "$(@($g.Labels) -join '+') x$cnt"
1306:                 if ($cnt -gt 1) { $t += $(if ($g.Limit -ge $cnt) { ' at once' } elseif ($g.Limit -le 1) { ' one after another' } else { " $($g.Limit) at a time" }) }
1307:                 $t
1308:             })
1309:         Write-Host "Concurrency: $($panelPlan.Text) - endpoint groups: $($groupTexts -join ', '); -PanelConcurrency $(if ($PanelConcurrency -gt 0) { $PanelConcurrency } else { '0 (no cap)' })"
1310:         if ($panelPendingRefusal) { Write-Host "pending     : the real run would be REFUSED - $panelPendingRefusal" -ForegroundColor Yellow }
1311: 
1312:         if (-not $DryRun) {
1313:             # Every member's `reserved` record BEFORE any member starts: a panel run that dies
1314:             # from here on leaves one record per planned member (inactive once this process is
1315:             # gone - the next run consumes them).
1316:             $written = New-Object System.Collections.Generic.List[string]
1317:             foreach ($slot in $panelSlots) {
1318:                 $launcherK = Get-EngineLauncher -Engine $slot.Engine -Launchers $engineLaunchers -CodexLauncher ([string]$codexExePath)
1319:                 $panelInfo = [pscustomobject]@{ id = $panelId; position = $slot.K; of = $panelRunners.Count; parent_pid = $PID; parent_start_time = $panelParentStart }
1320:                 $rec = New-PendingRecord -State 'reserved' -N $slot.N -Nn $slot.Nn -Reply $slot.Reply -Started (Get-IsoTimestamp) -Launcher $launcherK -ConsultId $slot.ConsultId -Engine $slot.Engine -Panel $panelInfo
1321:                 $rec.note = "reserved by review panel $panelShort (pid $PID); the member has not started"
1322:                 try { Write-PendingFile -Path $slot.RecordPath -Record $rec } catch {
1323:                     $why = ConvertTo-OneLine $_.Exception.Message
1324:                     foreach ($w in $written) { $null = Remove-PendingFile -Path $w }
1325:                     Stop-WithError "could not write the recovery record '$($slot.RecordPath)': $why; no panel member was started."
1326:                 }
1327:                 $written.Add($slot.RecordPath)
1328:             }
1329:             # The consumed records go now (their numbers are skipped) - never a path a member
1330:             # record now uses.
1331:             for ($i = 0; $i -lt @($panelPending.Items).Count; $i++) {
1332:                 $it = $panelPending.Items[$i]
1333:                 $num = $panelNumbers.Items[$i]
1334:                 $st = [string](Get-PropertyValue $it.Record 'state' '')
1335:                 if (-not (@($written) -icontains $it.Path)) {
1336:                     $rmError = Remove-PendingFile -Path $it.Path
1337:                     if ($rmError) { Write-Host "codex-consult: could not remove the consumed recovery record $($it.Path) ($rmError)" -ForegroundColor Yellow }
1338:                 }
1339:                 if ($num.Recovered) { Write-Host "codex-consult: recovered reservation n=$($num.N), nn=$($num.Nn) ($($it.Name): state '$st' of an interrupted run; $($it.Check.Check)); numbering continues past it." -ForegroundColor Yellow }
1340:                 else { Write-Host "codex-consult: cleared the recovery record of consult n=$($num.N), nn=$($num.Nn) ($($it.Name): state '$st'; $($it.Check.Check)); its ledger entry exists." -ForegroundColor Yellow }
1341:             }
1342:         } else {
1343:             for ($i = 0; $i -lt @($panelPending.Items).Count; $i++) {
1344:                 $it = $panelPending.Items[$i]
1345:                 $num = $panelNumbers.Items[$i]
1346:                 if (-not $it.Check.Active) { Write-Host "pending     : $($it.Path) (state '$([string](Get-PropertyValue $it.Record 'state' ''))', n=$($num.N), nn=$($num.Nn); $($it.Check.Check)): the real run recovers it; numbering continues past it." -ForegroundColor Yellow }
1347:             }
1348:         }
1349: 
1350:         # ------------------------------------------------------------------ launch + poll
1351:         [void][IO.Directory]::CreateDirectory($panelTmp)
1352:         Write-Utf8NoBom -Path $panelEmptyIn -Text ''
1353:         $panelBlocked = ''
1354:         while ($true) {
1355:             $progress = $false
1356:             foreach ($slot in $panelSlots) {
1357:                 if ($slot.State -ne 'running') { continue }
1358:                 $exited = $true
1359:                 try { $exited = $slot.Proc.HasExited } catch { $exited = $true }
1360:                 if ($exited) {
1361:                     try { $slot.Exit = $slot.Proc.ExitCode } catch { $slot.Exit = -1 }
1362:                     $slot.Wall = [math]::Round($slot.Watch.Elapsed.TotalSeconds, 1)
1363:                     $slot.State = 'done'
1364:                 } elseif ($slot.Watch.Elapsed.TotalSeconds -gt $slot.Guard) {
1365:                     $null = Stop-ProcessTree -Process $slot.Proc
1366:                     $slot.Exit = -1
1367:                     $slot.Wall = [math]::Round($slot.Watch.Elapsed.TotalSeconds, 1)
1368:                     $slot.State = 'killed'
