5195: # Process start time as a UTC round-trip string. $null: no such process. '': the
5196: # process exists but its start time cannot be read (e.g. another user's process).
5197: function Get-ProcessStartIso {
5198:     param([int]$ProcessId)
5199:     $p = $null
5200:     try { $p = Get-Process -Id $ProcessId -ErrorAction Stop } catch { return $null }
5201:     try { return $p.StartTime.ToUniversalTime().ToString('o', $script:Invariant) } catch { return '' }
5202: }
5203: 
5204: # Do two start times (UTC round-trip strings from Get-ProcessStartIso) name the same
5205: # process start? Windows reports a process's start time exactly. .NET on Linux derives
5206: # Process.StartTime from a boot time that every process computes for itself
5207: # (CLOCK_REALTIME_COARSE - CLOCK_BOOTTIME), so two processes reading the SAME pid get
5208: # values a few milliseconds apart. Outside Windows, less than one second apart counts
5209: # as the same start (a pid is not handed out again that fast).
5210: function Test-SameStartTime {
5211:     param([string]$A, [string]$B)
5212:     if ($A -eq $B) { return $true }
5213:     if ($script:OnWindows) { return $false }
5214:     $ta = [DateTimeOffset]::MinValue
5215:     $tb = [DateTimeOffset]::MinValue
5216:     $styles = [System.Globalization.DateTimeStyles]::AssumeUniversal
5217:     if (-not [DateTimeOffset]::TryParse($A, $script:Invariant, $styles, [ref]$ta)) { return $false }
5218:     if (-not [DateTimeOffset]::TryParse($B, $script:Invariant, $styles, [ref]$tb)) { return $false }
5219:     return ([math]::Abs($ta.UtcTicks - $tb.UtcTicks) -lt [TimeSpan]::TicksPerSecond)
5220: }
