5266: # Takes the task's ownership lock (see the section comment). Returns
5267: # { Acquired; Path; Stream; Record; Message } - the caller refuses when not Acquired.
5268: function Enter-TaskLock {
5269:     param([string]$TaskDir, [string]$Task, [string]$Panel = '')
5270:     $path = Join-Path $TaskDir '.consult.lock'
5271:     $share = if ($script:OnWindows) { [IO.FileShare]::Read } else { [IO.FileShare]::None }
5272:     $record = [pscustomobject]@{
5273:         pid        = $PID
5274:         start_time = (Get-ProcessStartIso -ProcessId $PID)
5275:         host       = [Environment]::MachineName
5276:         task       = $Task
5277:         started    = (Get-IsoTimestamp)
5278:     }
5279:     if ($Panel) { $record | Add-Member -NotePropertyName 'panel' -NotePropertyValue $Panel }
5280:     $fs = $null
5281:     try {
5282:         $fs = [IO.File]::Open($path, [IO.FileMode]::OpenOrCreate, [IO.FileAccess]::ReadWrite, $share)
5283:     } catch [System.IO.IOException] {
5284:         # The holder may not have replaced its predecessor's informational record
5285:         # yet: re-read briefly and name a pid only when that pid is alive.
5286:         $holder = $null
5287:         for ($attempt = 1; $attempt -le 8; $attempt++) {
5288:             $candidate = Read-LockContent -Path $path
5289:             $cpid = 0
5290:             if ($candidate -and [int]::TryParse([string](Get-PropertyValue $candidate 'pid' ''), [ref]$cpid) -and
5291:                 (Test-PidAlive -ProcessId $cpid -StartTime (ConvertTo-JsonText (Get-PropertyValue $candidate 'start_time' '')))) { $holder = $candidate; break }
5292:             Start-Sleep -Milliseconds 125
5293:         }
5294:         $who = 'a live process'
5295:         if ($holder) {
5296:             $who = "pid $(Get-PropertyValue $holder 'pid' '?') on $(Get-PropertyValue $holder 'host' '?') since $(Get-PropertyValue $holder 'started' '?')"
5297:             $holderPanel = [string](Get-PropertyValue $holder 'panel' '')
5298:             if ($holderPanel) { $who += " (review panel $($holderPanel.Substring(0, [Math]::Min(8, $holderPanel.Length))))" }
5299:         }
5300:         return (New-LockRefusal -Path $path -Message "another consultation or status update for task '$Task' is running: $path is held open by $who. Wait for it to finish; the lock is released when that process exits.")
5301:     } catch {
5302:         return (New-LockRefusal -Path $path -Message "could not open the lock '$path': $($_.Exception.Message)")
5303:     }
5304:     # Informational only (who holds it); nothing recoverable lives here.
5305:     try {
5306:         $bytes = $script:Utf8NoBom.GetBytes((ConvertTo-Json -InputObject $record -Compress) + "`n")
5307:         $fs.SetLength(0)
5308:         $fs.Position = 0
5309:         $fs.Write($bytes, 0, $bytes.Length)
5310:         $fs.Flush($true)
5311:     } catch { }
5312:     return [pscustomobject]@{ Acquired = $true; Path = $path; Stream = $fs; Record = $record; Message = '' }
5313: }
