5315: # Releases the ownership lock: close the handle, nothing else (the file stays).
5316: function Exit-TaskLock {
5317:     param($Lock)
5318:     if ($null -eq $Lock -or -not $Lock.Acquired -or $null -eq $Lock.Stream) { return }
5319:     $Lock.Acquired = $false
5320:     try { $Lock.Stream.Dispose() } catch { }
