4853: # The concurrency plan of a panel (0.4.x wave 21, D8 - endpoint-aware): members that reach the
4854: # same ENDPOINT run one after another, members of different endpoints at once. An endpoint
4855: # group is the members of one provider label, merged with every other label whose members
4856: # resolve to the same provider fingerprint (two labels on one base URL; every agy label - they
4857: # share one Google sign-in). A group runs 1 member at a time unless the roster's top-level
4858: # "parallel" raises its label (a merged group: the smallest limit of its labels); -Cap
4859: # (-PanelConcurrency) caps the total (0 = no cap, 1 = strictly one after another in roster
4860: # order). $Runners: the members Select-PanelMembers runs (State 'run'), in roster order.
4861: # { Groups (object[] of { Labels (string[]); Limit; Positions (int[] roster positions) });
4862: #   GroupOf (hashtable roster position -> group index); Cap; Effective (the most members
4863: #   that can run at once); Text ('at once' | 'one after another' | 'at most <k> at a time');
4864: #   Limits (ordered: label -> its group's limit, roster order) }
4865: function Get-PanelPlan {
4866:     param([object[]]$Runners, [hashtable]$Parallel = $null, [int]$Cap = 0)
4867:     $labels = New-Object System.Collections.Generic.List[string]
4868:     $fps = New-Object System.Collections.Hashtable ([StringComparer]::Ordinal)
4869:     foreach ($m in @($Runners | Where-Object { $_ })) {
4870:         $label = [string]$m.Entry.Provider
4871:         if (-not $fps.ContainsKey($label)) { $fps[$label] = New-Object System.Collections.Generic.List[string]; $labels.Add($label) }
4872:         $fp = ''
4873:         if ($m.Identity -and $m.Identity.Resolved) { $fp = [string]$m.Identity.Fingerprint }
4874:         if ($fp -and -not $fps[$label].Contains($fp)) { $fps[$label].Add($fp) }
4875:     }
4876:     # one group per label, then labels that share a fingerprint are merged (to a fixed point)
4877:     $groupOfLabel = New-Object System.Collections.Hashtable ([StringComparer]::Ordinal)
4878:     for ($i = 0; $i -lt $labels.Count; $i++) { $groupOfLabel[$labels[$i]] = $i }
4879:     $changed = $true
4880:     while ($changed) {
4881:         $changed = $false
4882:         for ($i = 0; $i -lt $labels.Count; $i++) {
4883:             for ($j = $i + 1; $j -lt $labels.Count; $j++) {
4884:                 $gi = $groupOfLabel[$labels[$i]]; $gj = $groupOfLabel[$labels[$j]]
4885:                 if ($gi -eq $gj) { continue }
4886:                 $shared = @($fps[$labels[$i]] | Where-Object { $fps[$labels[$j]].Contains($_) }).Count -gt 0
4887:                 if (-not $shared) { continue }
4888:                 $keep = [Math]::Min($gi, $gj); $drop = [Math]::Max($gi, $gj)
4889:                 foreach ($l in $labels) { if ($groupOfLabel[$l] -eq $drop) { $groupOfLabel[$l] = $keep } }
4890:                 $changed = $true
4891:             }
4892:         }
4893:     }
4894:     $groups = New-Object System.Collections.Generic.List[object]
4895:     $indexOf = @{}
4896:     $groupOf = @{}
4897:     foreach ($m in @($Runners | Where-Object { $_ })) {
4898:         $label = [string]$m.Entry.Provider
4899:         $gid = $groupOfLabel[$label]
4900:         if (-not $indexOf.ContainsKey($gid)) {
4901:             $indexOf[$gid] = $groups.Count
4902:             $groups.Add([pscustomobject]@{ Labels = (New-Object System.Collections.Generic.List[string]); Limit = 0; Positions = (New-Object System.Collections.Generic.List[int]) })
4903:         }
4904:         $g = $groups[$indexOf[$gid]]
4905:         if (-not $g.Labels.Contains($label)) { $g.Labels.Add($label) }
4906:         $g.Positions.Add([int]$m.Entry.Position)
4907:         $groupOf[[int]$m.Entry.Position] = $indexOf[$gid]
4908:     }
4909:     $effective = 0
4910:     $limits = [ordered]@{}
4911:     $out = New-Object System.Collections.Generic.List[object]
4912:     foreach ($g in $groups) {
4913:         $limit = 0
4914:         foreach ($l in $g.Labels) {
4915:             $v = 1
4916:             if ($null -ne $Parallel -and $Parallel.ContainsKey($l)) { $v = [int]$Parallel[$l] }
4917:             if ($limit -eq 0 -or $v -lt $limit) { $limit = $v }
4918:         }
4919:         $effective += [Math]::Min($limit, $g.Positions.Count)
4920:         $out.Add([pscustomobject]@{ Labels = [string[]]$g.Labels.ToArray(); Limit = $limit; Positions = [int[]]$g.Positions.ToArray() })
4921:     }
4922:     foreach ($l in $labels) { $limits[$l] = $out[$indexOf[$groupOfLabel[$l]]].Limit }
4923:     if ($Cap -gt 0 -and $Cap -lt $effective) { $effective = $Cap }
4924:     $count = @($Runners | Where-Object { $_ }).Count
4925:     $text = if ($effective -ge $count) { 'at once' } elseif ($effective -le 1) { 'one after another' } else { "at most $effective at a time" }
4926:     return [pscustomobject]@{ Groups = [object[]]$out.ToArray(); GroupOf = $groupOf; Cap = $Cap; Effective = $effective; Text = $text; Limits = $limits }
4927: }
